using Clock=std::chrono::steady_clock;
static double ms(Clock::time_point t){return std::chrono::duration<double,std::milli>(Clock::now()-t).count();}
static NSString* ns(const std::string&s){return [NSString stringWithUTF8String:s.c_str()];}
static void demand(bool ok,const std::string&s){if(!ok)throw std::runtime_error(s);}
static std::vector<char> readfile(const std::string&p){std::ifstream f(p,std::ios::binary|std::ios::ate);demand(bool(f),"open "+p);auto len=f.tellg();demand(len>=0,"length");std::vector<char>b((size_t)len);f.seekg(0);f.read(b.data(),len);demand(bool(f),"read "+p);return b;}
static void writefile(const std::string&p,const void*b,size_t len){std::ofstream f(p,std::ios::binary);f.write((const char*)b,len);demand(bool(f),"write "+p);}
static void jsonfile(const std::string&p,id d){NSError*e=nil;NSData*b=[NSJSONSerialization dataWithJSONObject:d options:NSJSONWritingPrettyPrinted|NSJSONWritingSortedKeys error:&e];demand(b!=nil,e?e.description.UTF8String:"json");writefile(p,b.bytes,b.length);}
static double edges64[25];static float edges32[25];
static void edges(){for(int l=0;l<=24;l++){edges64[l]=.9*(1.-2.*l/24.);edges32[l]=(float)edges64[l];}}
struct Input {uint32_t n,seed;std::vector<int32_t> layer;std::vector<double> t64,v64,ref;std::vector<float>t,v;double read_ms,quantization_ms;};
static Input input(const std::string&prefix){Input d;auto start=Clock::now();auto b=readfile(prefix+".3ain");demand(b.size()>=16&&memcmp(b.data(),"3AIN",4)==0,"3AIN magic");uint32_t version;memcpy(&version,b.data()+4,4);memcpy(&d.n,b.data()+8,4);memcpy(&d.seed,b.data()+12,4);demand(version==1&&d.n>0&&d.seed==20261112&&b.size()==16+20ull*d.n,"3AIN version/count/seed/length");d.layer.resize(d.n);d.t64.resize(d.n);d.v64.resize(d.n);memcpy(d.layer.data(),b.data()+16,4ull*d.n);memcpy(d.t64.data(),b.data()+16+4ull*d.n,8ull*d.n);memcpy(d.v64.data(),b.data()+16+12ull*d.n,8ull*d.n);auto r=readfile(prefix+".reference.f64");demand(r.size()==24ull*d.n,"reference exact 3n FP64 coordinates");d.ref.resize(3ull*d.n);memcpy(d.ref.data(),r.data(),r.size());d.read_ms=ms(start);start=Clock::now();d.t.resize(d.n);d.v.resize(d.n);for(uint32_t i=0;i<d.n;i++){demand(d.layer[i]>=0&&d.layer[i]<24&&std::isfinite(d.t64[i])&&std::isfinite(d.v64[i]),"invalid input");d.t[i]=(float)d.t64[i];d.v[i]=(float)d.v64[i];}d.quantization_ms=ms(start);return d;}
__attribute__((noinline)) static void cpuPlace(const Input&d,float*out,size_t begin,size_t end){
 for(size_t i=begin;i<end;i++){const float pi=3.14159265358979323846f;float phi=pi*(2.f*d.t[i]-1.f);int l=d.layer[i];float zt=edges32[l],zb=edges32[l+1];float z=zb+(zt-zb)*(.12f+(1.f-2.f*.12f)*d.v[i]);float th=std::acos(std::clamp(z,-1.f,1.f)),st=std::sin(th);out[3*i]=st*std::sin(phi);out[3*i+1]=-st*std::cos(phi);out[3*i+2]=std::cos(th);}
}
class Pool{
 std::vector<std::thread> workers;std::mutex m;std::condition_variable wake,done;std::function<void(size_t,size_t)>job;std::atomic<size_t>next{0};size_t count=0,generation=0,left=0;bool stop=false;
public:
 explicit Pool(unsigned n){demand(n>0,"worker count");for(unsigned i=0;i<n;i++)workers.emplace_back([this]{size_t seen=0;while(true){std::unique_lock<std::mutex>lock(m);wake.wait(lock,[&]{return stop||seen!=generation;});if(stop)return;seen=generation;lock.unlock();while(true){size_t k=next.fetch_add(4096,std::memory_order_relaxed);if(k>=count)break;job(k,std::min(k+4096,count));}lock.lock();if(--left==0)done.notify_one();}});}
 void run(size_t n,std::function<void(size_t,size_t)>fn){std::unique_lock<std::mutex>lock(m);count=n;job=std::move(fn);next=0;left=workers.size();++generation;wake.notify_all();done.wait(lock,[&]{return left==0;});}
 ~Pool(){{std::lock_guard<std::mutex>lock(m);stop=true;}wake.notify_all();for(auto&t:workers)t.join();}
};
struct Check{size_t expected=0,actual=0,nonfinite=0,error_count=0,outside=0;double max_error=0,max_radius_error=0;bool pass=false;};
static Check validate(const float*out,size_t count,const std::vector<double>&ref,const std::vector<int32_t>&layer){
 Check c;c.expected=3*layer.size();c.actual=count;if(count!=c.expected||ref.size()!=c.expected)return c;
 for(size_t i=0;i<count;i++){if(!std::isfinite(out[i])||!std::isfinite(ref[i])){c.nonfinite++;continue;}double e=std::abs(double(out[i])-ref[i]);c.max_error=std::max(c.max_error,e);c.error_count+=e>5e-4;}
 for(size_t i=0;i<layer.size();i++){double x=out[3*i],y=out[3*i+1],z=out[3*i+2],r=std::hypot(x,y,z),h=z/(r?r:1);int l=layer[i];if(!std::isfinite(r)||r==0||l<0||l>=24||!(h<=edges64[l]&&h>=edges64[l+1]))c.outside++;if(std::isfinite(r))c.max_radius_error=std::max(c.max_radius_error,std::abs(r-1.));}
 c.pass=c.nonfinite==0&&c.error_count==0&&c.outside==0;return c;
}
static NSDictionary* checkJSON(const Check&c){return @{ @"pass":@(c.pass),@"expected_coordinates":@(c.expected),@"actual_coordinates":@(c.actual),@"nonfinite":@(c.nonfinite),@"coordinates_over_5e_4":@(c.error_count),@"max_abs_error_vs_raw_fp64":@(c.max_error),@"outside_band":@(c.outside),@"max_unit_radius_error":@(c.max_radius_error)};}
static void selftest(){edges();std::vector<int32_t>layer={12};double z=(edges64[12]+edges64[13])/2;std::vector<double>ref={std::sqrt(1-z*z),0,z};std::vector<float>x(ref.begin(),ref.end());unsigned passed=0;demand(validate(x.data(),3,ref,layer).pass,"positive check");passed++;demand(!validate(x.data(),2,ref,layer).pass,"truncation check");passed++;auto y=x;y[0]=NAN;demand(!validate(y.data(),3,ref,layer).pass,"NaN check");passed++;y=x;y[1]=INFINITY;demand(!validate(y.data(),3,ref,layer).pass,"infinity check");passed++;y=x;y[0]+=.001f;demand(!validate(y.data(),3,ref,layer).pass,"coordinate error check");passed++;y=x;y[2]=.7f;demand(validate(y.data(),3,ref,layer).outside==1,"band check");passed++;y={0,0,0};demand(!validate(y.data(),3,ref,layer).pass,"zero radius check");passed++;auto badref=ref;badref[0]=NAN;demand(!validate(x.data(),3,badref,layer).pass,"reference NaN check");passed++;printf("{\"checker_cases_passed\":%u,\"checker_cases_total\":8}\n",passed);}
int main(int argc,char**argv){@autoreleasepool{try{
 if(argc==2&&std::string(argv[1])=="--self-test"){selftest();return 0;}
 if(argc==3&&std::string(argv[1])=="--prepare"){id<MTLDevice>device=MTLCreateSystemDefaultDevice();demand(device!=nil,"No Metal device");NSError*error=nil;MTLCompileOptions*o=[MTLCompileOptions new];o.mathMode=MTLMathModeSafe;o.mathFloatingPointFunctions=MTLMathFloatingPointFunctionsPrecise;NSString*s=[NSString stringWithContentsOfFile:ns(argv[2]) encoding:NSUTF8StringEncoding error:&error];demand(s!=nil,"shader read");id<MTLLibrary>l=[device newLibraryWithSource:s options:o error:&error];demand(l!=nil,error?error.description.UTF8String:"shader compile");id<MTLComputePipelineState>p=[device newComputePipelineStateWithFunction:[l newFunctionWithName:@"place_markers"] error:&error];demand(p!=nil,error?error.description.UTF8String:"pipeline");printf("{\"device\":\"%s\",\"safe_precise_pipeline_compiled\":true,\"max_threads\":%lu}\n",device.name.UTF8String,(unsigned long)p.maxTotalThreadsPerThreadgroup);return 0;}
 demand(argc==6,"usage: native_bench INPUT_PREFIX SHADER OUT_PREFIX WORKERS REPEATS");edges();std::string out=argv[3];for(const char*suffix:{".json",".gpu-final.f32",".cpu-single-final.f32",".cpu-final.f32",".failure.json"})demand(!std::filesystem::exists(out+suffix),"Preserve existing output "+out+suffix);Input d=input(argv[1]);unsigned workers=std::stoul(argv[4]),repeats=std::stoul(argv[5]);demand(workers>0&&workers<=256&&repeats>0,"workers/repeats");
 auto compileStart=Clock::now();id<MTLDevice>device=MTLCreateSystemDefaultDevice();demand(device!=nil,"No Metal device");demand([device.name containsString:@"Apple"],"Expected Apple Metal device");id<MTLCommandQueue>queue=[device newCommandQueue];demand(queue!=nil,"No Metal command queue");NSError*error=nil;MTLCompileOptions*options=[MTLCompileOptions new];options.mathMode=MTLMathModeSafe;options.mathFloatingPointFunctions=MTLMathFloatingPointFunctionsPrecise;
 NSString*shader=[NSString stringWithContentsOfFile:ns(argv[2]) encoding:NSUTF8StringEncoding error:&error];demand(shader!=nil,"shader read");id<MTLLibrary>lib=[device newLibraryWithSource:shader options:options error:&error];demand(lib!=nil,error?error.description.UTF8String:"compile");id<MTLComputePipelineState>pipe=[device newComputePipelineStateWithFunction:[lib newFunctionWithName:@"place_markers"] error:&error];demand(pipe!=nil,error?error.description.UTF8String:"pipeline");double compile_ms=ms(compileStart);
 demand(12ull*d.n<=device.maxBufferLength,"Output buffer exceeds Metal limit");demand(24ull*d.n<=device.recommendedMaxWorkingSetSize/4,"GPU buffers exceed quarter of recommended working set");
 auto t=Clock::now();id<MTLBuffer>bl=[device newBufferWithLength:4ull*d.n options:MTLResourceStorageModeShared],bt=[device newBufferWithLength:4ull*d.n options:MTLResourceStorageModeShared],bv=[device newBufferWithLength:4ull*d.n options:MTLResourceStorageModeShared],bo=[device newBufferWithLength:12ull*d.n options:MTLResourceStorageModeShared];demand(bl&&bt&&bv&&bo,"Metal allocation");double allocation_ms=ms(t);t=Clock::now();memcpy(bl.contents,d.layer.data(),4ull*d.n);memcpy(bt.contents,d.t.data(),4ull*d.n);memcpy(bv.contents,d.v.data(),4ull*d.n);double upload_ms=ms(t);std::vector<float>host(3ull*d.n);NSMutableArray*gpu=[NSMutableArray array],*single=[NSMutableArray array],*multi=[NSMutableArray array];
 auto dispatch=[&](){auto begin=Clock::now();id<MTLCommandBuffer>cb=[queue commandBuffer];demand(cb!=nil,"No Metal command buffer");id<MTLComputeCommandEncoder>enc=[cb computeCommandEncoder];demand(enc!=nil,"No Metal compute encoder");[enc setComputePipelineState:pipe];[enc setBuffer:bl offset:0 atIndex:0];[enc setBuffer:bt offset:0 atIndex:1];[enc setBuffer:bv offset:0 atIndex:2];[enc setBuffer:bo offset:0 atIndex:3];[enc setBytes:edges32 length:sizeof(edges32) atIndex:4];[enc setBytes:&d.n length:4 atIndex:5];[enc dispatchThreads:MTLSizeMake(d.n,1,1) threadsPerThreadgroup:MTLSizeMake(std::min<NSUInteger>(256,pipe.maxTotalThreadsPerThreadgroup),1,1)];[enc endEncoding];double encode=ms(begin);auto submit=Clock::now();[cb commit];[cb waitUntilCompleted];double complete=ms(submit),resident=ms(begin);demand(cb.status==MTLCommandBufferStatusCompleted,cb.error?cb.error.description.UTF8String:"Metal command incomplete");double device_ms=(cb.GPUEndTime-cb.GPUStartTime)*1000.;demand(device_ms>0&&std::isfinite(device_ms),"invalid GPU timestamps");return @{ @"resident_encode_submit_complete_ms":@(resident),@"encode_ms":@(encode),@"submit_wait_ms":@(complete),@"gpu_device_ms":@(device_ms)};};
 for(unsigned w=0;w<3;w++)dispatch();
 for(unsigned k=0;k<repeats;k++){@autoreleasepool{auto e2eStart=Clock::now();NSMutableDictionary*trial=[dispatch() mutableCopy];t=Clock::now();memcpy(host.data(),bo.contents,12ull*d.n);trial[@"full_output_copy_ms"]=@(ms(t));trial[@"resident_plus_full_output_copy_ms"]=@(ms(e2eStart));t=Clock::now();Check c=validate(host.data(),host.size(),d.ref,d.layer);trial[@"validation_ms"]=@(ms(t));trial[@"validation"]=checkJSON(c);trial[@"trial"]=@(k);[gpu addObject:trial];demand(c.pass,"GPU pointwise validation failed");}}
 writefile(out+".gpu-final.f32",host.data(),host.size()*4);
 for(unsigned w=0;w<3;w++)cpuPlace(d,host.data(),0,d.n);
 for(unsigned k=0;k<repeats;k++){t=Clock::now();cpuPlace(d,host.data(),0,d.n);double duration=ms(t);t=Clock::now();Check c=validate(host.data(),host.size(),d.ref,d.layer);double validation_ms=ms(t);[single addObject:@{@"trial":@(k),@"placement_ms":@(duration),@"validation_ms":@(validation_ms),@"validation":checkJSON(c)}];demand(c.pass,"singleCPU pointwise validation failed");}
 writefile(out+".cpu-single-final.f32",host.data(),host.size()*4);
 auto poolStart=Clock::now();Pool pool(workers);double pool_create_ms=ms(poolStart);auto runPool=[&](){pool.run(d.n,[&](size_t b,size_t e){cpuPlace(d,host.data(),b,e);});};for(unsigned w=0;w<3;w++)runPool();
 for(unsigned k=0;k<repeats;k++){t=Clock::now();runPool();double duration=ms(t);t=Clock::now();Check c=validate(host.data(),host.size(),d.ref,d.layer);double validation_ms=ms(t);[multi addObject:@{@"trial":@(k),@"placement_including_barrier_ms":@(duration),@"validation_ms":@(validation_ms),@"validation":checkJSON(c)}];demand(c.pass,"multiCPU pointwise validation failed");}
 auto singleFinal=readfile(out+".cpu-single-final.f32");bool cpu_identical=singleFinal.size()==host.size()*4&&memcmp(singleFinal.data(),host.data(),singleFinal.size())==0;demand(cpu_identical,"single and multicore CPU coordinates differ");writefile(out+".cpu-final.f32",host.data(),host.size()*4);
 NSDictionary*result=@{@"schema":@1,@"experiment":@"native-metal-stock-trig-fp32",@"n":@(d.n),@"coordinate_count":@(3ull*d.n),@"seed":@(d.seed),@"bands":@24,@"cap":@.9,@"margin":@.12,@"warmups":@3,@"repeats":@(repeats),@"worker_count":@(workers),@"cpu_single_multi_bit_identical":@(cpu_identical),@"cpu_chunk_markers":@4096,@"device":device.name,@"device_registry_id":@(device.registryID),@"unified_memory":@(device.hasUnifiedMemory),@"max_buffer_length":@(device.maxBufferLength),@"recommended_max_working_set_bytes":@(device.recommendedMaxWorkingSetSize),@"requested_gpu_buffer_bytes":@(24ull*d.n),@"allocated_gpu_buffer_bytes":@(bl.allocatedSize+bt.allocatedSize+bv.allocatedSize+bo.allocatedSize),@"process_metal_allocated_bytes":@(device.currentAllocatedSize),@"metal_math_mode":@"safe",@"metal_floating_point_functions":@"precise",@"cpu_compile":@"clang++ -O3 -fno-fast-math -ffp-contract=off",@"input_read_and_reference_read_ms":@(d.read_ms),@"fp64_to_fp32_input_conversion_ms":@(d.quantization_ms),@"device_queue_shader_pipeline_setup_ms":@(compile_ms),@"metal_shared_buffer_allocation_ms":@(allocation_ms),@"input_memcpy_into_unified_shared_buffers_ms":@(upload_ms),@"cpu_worker_pool_creation_ms":@(pool_create_ms),@"gpu_trials":gpu,@"cpu_single_trials":single,@"cpu_multi_trials":multi,@"notes":@[@"Input generation/file IO, FP32 conversion, Metal setup/allocation/input copy, output copy and validation are outside resident execution clocks.",@"Apple unified memory: input/output copies are CPU memcpy to/from shared Metal buffers, not discrete-GPU PCIe transfers.",@"Every trial output coordinate is compared against stock JS FP64 coordinates computed from the original FP64 inputs.",@"All geometry engines use acos then sin/cos; GPU and CPU use FP32 inputs/edges; reference remains FP64.",@"GPU every timed run is followed by full output copy/validation; CPU every run by validation; this cadence differs from stock WebGL timing.",@"Fixed method order is GPU, CPU single, CPU multicore; warmups precede each method; no randomized interleaving.",@"CPU workers persist and share dynamically claimed4096-marker chunks; dispatch and completion barrier are included.",@"Neither CPU affinity nor exclusive machine access is asserted."]};jsonfile(out+".json",result);printf("%s n=%u device=%s repeats=%u workers=%u all_validated=true\n",out.c_str(),d.n,device.name.UTF8String,repeats,workers);return 0;
 }catch(const std::exception&e){fprintf(stderr,"%s\n",e.what());return 1;}}}
